SET title = #{title}, author = #{author}, village_name = #{villageName}, theme_name = #{themeName}, image_url = #{imageUrl}, content = #{content}

    , publish_status = #{publish_status}

WHERE id = #{id}

UPDATE village_news 
SET is_deleted = '1'
WHERE id = #{id}

