SELECT COUNT(0) FROM village_news vn WHERE vn.is_deleted = '0'
AND (vn.title LIKE CONCAT('%', #{keyword}, '%') OR vn.author LIKE CONCAT('%', #{keyword}, '%') OR vn.village_name LIKE CONCAT('%', #{keyword}, '%') OR vn.theme_name LIKE CONCAT('%', #{keyword}, '%'))
AND vn.publish_status = #{publish_status}

SELECT vn.id, vn.title, vn.author, vn.village_name as villageName, vn.theme_name as themeName, vn.image_url as imageUrl, vn.created_time as createTime, vn.publish_status as publishStatus, vn.content FROM village_news vn WHERE vn.is_deleted = '0'
AND (vn.title LIKE CONCAT('%', #{keyword}, '%') OR vn.author LIKE CONCAT('%', #{keyword}, '%') OR vn.village_name LIKE CONCAT('%', #{keyword}, '%') OR vn.theme_name LIKE CONCAT('%', #{keyword}, '%'))
AND vn.publish_status = #{publish_status}
ORDER BY vn.id DESC LIMIT #{offSet,jdbcType=INTEGER}, #{pageRow,jdbcType=INTEGER}
